// Browser storage can be restricted; saved UI preferences have an in-memory fallback.
function safeStore(name){const memory=new Map();return {getItem(key){try{return window[name].getItem(key)??memory.get(key)??null;}catch{return memory.get(key)??null;}},setItem(key,value){memory.set(key,String(value));try{window[name].setItem(key,String(value));}catch{}},removeItem(key){memory.delete(key);try{window[name].removeItem(key);}catch{}}};}
const localStore=safeStore('localStorage'),sessionStore=safeStore('sessionStorage');
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
