const avatar=(u=S.user)=>u?.photo_url?`<img class="avatar-photo small" src="${esc(u.photo_url)}" alt="Profile photo">`:`<span class="initials small">${esc((u?.first_name?.[0]||'C')+(u?.last_name?.[0]||''))}</span>`;
const badge=s=>`<span class="badge ${esc(s.toLowerCase().replaceAll(' ','-'))}">${esc(s)}</span>`;
const btn=(label,action,ico='',primary=false,extra='')=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const heading=(title,sub='',actions='')=>`<div class="page-heading"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div><div class="row wrap">${actions}</div></div>`;
const empty=(title,sub='',action='')=>`<div class="empty-state">${icon('document')}<h3>${esc(title)}</h3><p>${esc(sub)}</p>${action}</div>`;
const footer=()=>`<footer class="page-footer"><span><i class="status-dot"></i> Workspace connected</span><span>Colleague Workspace &middot; Account-restricted access &middot; v3.0</span></footer>`;
function fmt(v,mode='short'){if(!v)return '\u2014';const d=new Date(v.length===10?v+'T12:00:00+05:30':v);return mode==='numeric'?new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Kolkata'}).format(d).replaceAll('/','-'):new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',...(mode==='full'?{year:'numeric'}:{}),timeZone:'Asia/Kolkata'}).format(d);}
const clock=v=>v?new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Kolkata'}).format(new Date(v)):'\u2014';
function duration(v,pad=true){let s=Math.max(0,Math.floor(Number(v)||0));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map((x,i)=>i===0&&!pad?String(x):String(x).padStart(2,'0')).join(':');}
async function api(path,options={}){let res;const multipart=options.body instanceof FormData;try{res=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(!multipart?{'Content-Type':'application/json'}:{}),...(S.csrf?{'X-CSRF-Token':S.csrf}:{}),...options.headers},body:options.body===undefined?undefined:multipart?options.body:JSON.stringify(options.body)});}catch(e){throw new Error('Cannot reach the backend. Keep the server window open and reload.');}let data;try{data=await res.json();}catch(e){throw new Error('Unexpected server response. Please restart the server.');}if(!res.ok){const err=new Error(Array.isArray(data.detail)?data.detail.map(x=>x.msg).join('; '):data.detail||'Request failed.');err.status=res.status;throw err;}return data;}
function toast(message,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.setAttribute('role',error?'alert':'status');e.innerHTML=icon(error?'alert':'checkcircle')+`<span>${esc(message)}</span>`;$('#toast-root').append(e);setTimeout(()=>e.remove(),5000);}
function modal(title,body){const m=$('#modal');if(m.open)m.close();m.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;m.showModal();}
const closeModal=()=>$('#modal').close();
const actions=(label='Submit')=>`<p class="error-text" role="alert"></p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">${label}</button></div>`;
const field=(label,name,type='text',value='',attrs='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;
const area=(label,name,placeholder='',value='',required=true)=>`<div class="field full"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" placeholder="${esc(placeholder)}" ${required?'required minlength="5"':''} maxlength="4000">${esc(value)}</textarea></div>`;
const select=(label,name,opts,value='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${opts.map(o=>{const v=typeof o==='string'?o:o.value;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(typeof o==='string'?o:o.label)}</option>`;}).join('')}</select></div>`;
function closeOverlays(){$('#overlay-root').innerHTML='';document.body.style.overflow='';$('#people-results')?.remove();}
function nav(route){closeOverlays();if(location.hash==='#'+route)renderRoute();else location.hash=route;}
function shiftLabel(shift=S.dashboard?.shift){return shift?`${time12(shift.start_time)} &ndash; ${time12(shift.end_time)}`:'8:30 PM &ndash; 4:30 AM';}
function time12(t){if(!t)return '';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function clock12(t){return t?new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'Asia/Kolkata'}).format(new Date(t)):'--:--';}
function checkLabel(d=S.dashboard){return d?.state==='checked_in'?'Check Out':d?.state==='checked_out'?'View Attendance':'Check In';}
function shell(){
 document.body.classList.toggle('compact',!!S.user.preferences.compact_view);
 const section=S.route==='dashboard'?'Overview':app(S.route).name;
 const link=id=>`<button class="side-link ${S.route===id?'active':''}" data-nav="${id}" aria-label="${esc(app(id).name)}">${icon(app(id).ico)}<span>${esc(app(id).name)}</span>${id==='tasks'&&S.dashboard.tasks.length?`<b class="side-count">${S.dashboard.tasks.length}</b>`:''}</button>`;
 $('#app').innerHTML=`<aside class="sidebar" aria-label="Main navigation">
 <button class="sidebar-brand" data-nav="dashboard" aria-label="American Express-inspired workspace home"><img src="${A}amex-logo.svg" alt="American Express"><span>Colleague<br><strong>Workspace</strong></span></button>
 <div class="side-label">MY WORKSPACE</div><nav class="side-links">${['dashboard','time','payslips','documents','tasks'].map(link).join('')}</nav>
 <div class="side-label services-label">COLLEAGUE SERVICES</div><nav class="side-links">${[...(S.user.role==='admin'?['employees','attendance-admin','attendance-requests','document-centre','admin']:['performance','expenses','regularize','team']),'it','policies'].map(link).join('')}<button class="side-link" data-action="apps" aria-label="All Apps">${icon('grid')}<span>All Apps</span>${icon('chevron')}</button></nav>
 <div class="side-bottom"><button class="sidebar-shift" data-action="shift-settings"><span class="shift-moon">${icon('moon')}</span><span><b>Night shift</b><small>${esc(S.dashboard.shift.start_time)} &rarr; ${esc(S.dashboard.shift.end_time)} &middot; IST</small></span>${icon('settings')}</button><button class="sidebar-help" data-action="guide">${icon('help')} Help &amp; workspace guide</button><span class="local-mark">COLLEAGUE WORKSPACE &middot; V3.0</span></div></aside>
 <header class="topbar"><div class="header-left"><button class="mobile-apps icon-button" data-action="apps" aria-label="All Apps">${icon('grid')}</button><div class="header-brand"><b>American Express</b><span>COLLEAGUE WORKSPACE</span></div><div class="header-divider"></div><div class="people-search">${icon('search')}<input id="people-search" placeholder="Find a colleague..." aria-label="Search for people" autocomplete="off"><span class="search-hint">Search</span></div></div>
 <div class="header-right"><button class="top-check" data-action="punch">${icon(S.dashboard.state==='checked_in'?'logout':'login')}<span>${checkLabel()}</span></button><button class="icon-button notification-button" data-action="notifications" aria-label="Notifications">${icon('bell')}<span id="unread-count" class="notification-count">${S.dashboard.unread}</span></button><button class="account-trigger" data-action="account" aria-label="Account menu">${avatar()}<span>${esc(S.user.first_name)}<small>${S.user.role==='admin'?'Administrator':'Colleague'}</small></span>${icon('chevrondown')}</button></div></header>
 <main class="page" id="page"></main>`;
}
async function refresh(){S.dashboard=await api('/dashboard');S.clockSync=Date.now();S.user=S.dashboard.user;shell();await renderRoute();}
async function start(){try{const info=await api('/session');if(info.setup_required){setupPage();return;}if(!info.authenticated){loginPage();return;}S.user=info.user;S.csrf=info.csrf;if(S.user.must_change_password){changePasswordPage();return;}S.route=location.hash.slice(1)||'dashboard';await refresh();}catch(e){$('#app').innerHTML=`<div class="boot">${icon('alert')}<h2>The workspace could not open</h2><p style="max-width:450px;text-align:center;padding:20px">${esc(e.message)}</p>${btn('Try again','reload','',true)}<p class="tiny muted">Start the project with START_WINDOWS.bat and open the address shown in the terminal.</p></div>`;}}
function loginPage(){accessPage('employee');}
async function renderRoute(){if(!S.user)return;const epoch=++S.epoch;S.route=location.hash.slice(1)||'dashboard';const root=$('#page');if(!root)return;$$('.side-link').forEach(e=>e.classList.toggle('active',e.dataset.nav===S.route));root.innerHTML='<div class="loading-section"><span class="spinner"></span></div>';try{let content;switch(S.route){case'dashboard':content=await dashboardPage();break;case'tasks':content=await tasksPage();break;case'time':content=await timePage();break;case'regularize':content=await regularizePage();break;case'attendance-requests':content=await attendanceRequestsPage();break;case'profile':content=profilePage();break;case'members':content=await membersPage();break;case'performance':content=await goalsPage();break;case'recruitment':content=await jobsPage();break;case'it':case'helpdesk':case'admin-services':content=await ticketsPage();break;case'flows':content=await requestsPage();break;case'documents':content=await documentsPage();break;case'payslips':case'compensation':content=await documentsPage('payslip');break;case'employees':content=await employeesPage();break;case'team':content=await managerTeamPage();break;case'attendance-admin':content=await adminAttendancePage();break;case'document-centre':content=await documentCentrePage();break;case'expenses':content=await requestsPage('expense');break;case'travel':content=await requestsPage('travel');break;case'policies':content=policiesPage();break;case'org':content=await orgPage();break;case'vibe':content=await postsPage();break;case'admin':content=await adminPage();break;case'talent':case'benefits':case'refyne':case'learn':content=servicePage();break;default:content=empty('Page not found','Open All Apps to return to your workspace.');}if(epoch!==S.epoch)return;root.innerHTML=content+footer();if(S.route==='tasks')taskTable();if(S.route==='admin'&&S.user.role==='admin')adminTable();updateClock();}catch(e){if(epoch!==S.epoch)return;if(e.status===401){loginPage();toast('Your session expired. Sign in again.',true);return;}root.innerHTML=empty('Unable to open this section',e.message,btn('Try again','retry','clock'))+footer();}}
async function loadMetrics(){[S.metrics,S.balances]=await Promise.all([api(`/attendance?period=${S.period}${S.end?'&end='+S.end:''}`),api('/leave-balances')]);}
function chart(data){
 const w=660,h=233,left=32,right=12,top=18,bottom=36,ph=h-top-bottom,pw=w-left-right,n=data.length;
 const max=Math.ceil(Math.max(12,...data.map(r=>Math.max(r.worked_seconds,r.off_seconds)/3600))/3)*3;
 let out=`<svg class="attendance-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Night-shift attendance, actual logged hours and late arrival">`;
 for(let i=0;i<=4;i++){const y=top+i*ph/4;out+=`<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e6edf4" stroke-dasharray="${i===4?'0':'3 5'}"/><text x="${left-10}" y="${y+4}" text-anchor="end" fill="#8290a5" font-size="10">${max-i*max/4}</text>`;}
 data.forEach((r,i)=>{const x=left+(i+.5)*pw/n,bw=n>10?10:24,work=r.worked_seconds/3600*ph/max,off=r.off_seconds/3600*ph/max,late=r.late_seconds/3600*ph/max;out+=`<g><title>${esc(fmt(r.date,'full'))}: ${duration(r.worked_seconds)} worked; ${duration(r.late_seconds)} late</title>`;if(off)out+=`<rect x="${x-bw/2}" y="${top+ph-off}" width="${bw}" height="${off}" rx="5" fill="#dce5ef"/>`;if(work)out+=`<rect x="${x-bw/2}" y="${top+ph-work}" width="${bw}" height="${work}" rx="5" fill="${i===n-2?'#006fcf':'#76b9f2'}"/>`;if(late)out+=`<rect x="${x+bw/2+3}" y="${top+ph-late}" width="4" height="${Math.max(2,late)}" rx="2" fill="#eda84a"/>`;if(n<=10||i%5===0||i===n-1)out+=`<text x="${x}" y="${top+ph+24}" text-anchor="middle" fill="#6b7c92" font-size="10">${esc(fmt(r.date))}</text>`;out+='</g>';});return out+'</svg>';
}
function metricsHTML(){const m=S.metrics;return `<section class="card metrics-card"><div class="card-heading"><div><h2>Attendance overview</h2><p class="section-subtitle">Your night-shift hours, at a glance</p></div><select id="metrics-period" class="metrics-period" aria-label="Attendance period"><option value="week" ${S.period==='week'?'selected':''}>This week</option><option value="month" ${S.period==='month'?'selected':''}>Last 30 days</option></select></div><div class="metric-strip">${[[duration(m.avg_work,false),'Average work time'],[duration(m.avg_late),'Average late arrival'],[duration(m.avg_overtime),'Average extra time']].map(([v,l])=>`<div><div class="metric-value">${v}</div><div class="metric-label">${l}</div></div>`).join('')}</div>${chart(m.chart)}<div class="chart-legend">${[['#76b9f2','Logged hours'],['#dce5ef','Weekly off / leave'],['#eda84a','Late arrival']].map(([c,l])=>`<span class="legend-item"><i class="legend-swatch" style="background:${c}"></i>${l}</span>`).join('')}</div><div class="chart-dates">${fmt(m.start)} &ndash; ${fmt(m.end,'full')} &middot; IST &middot; Your saved attendance records</div></section>`;}
function balancesHTML(){return `<section class="card balance-card"><div class="card-heading"><div><h2>Time for yourself</h2><p class="section-subtitle">Your available leave balances</p></div><button class="link-button" data-action="leave">Apply leave ${icon('chevron')}</button></div><div class="balance-grid">${S.balances.map(b=>`<button class="balance-tile ${b.type==='Earned Leave'?'featured':''}" data-action="leave" data-type="${esc(b.type)}" title="${esc(b.type)}: ${b.pending_days} day(s) pending"><span class="balance-top">${b.balance===null?icon('leave'):`<span class="balance-number">${b.balance}</span><small>days</small>`}</span><span class="balance-name">${esc(b.type)}</span>${b.pending_days?`<span class="balance-pending">${b.pending_days} pending</span>`:''}</button>`).join('')}</div><p class="balance-footnote">Balances are allocated by your administrator.</p></section>`;}
function eventHTML(){const t=S.eventTab;if(t==='Leave'&&S.dashboard.events.length)return S.dashboard.events.map(e=>`<div class="row team-event">${avatar(e)}<div><h3>${esc(e.first_name+' '+e.last_name)}</h3><p>${esc(e.type)}</p></div></div>`).join('');return `<div class="team-orbit"><span class="team-initial a">${icon('users')}</span><span class="team-initial b">${icon('moon')}</span><span class="team-initial c">${icon('user')}</span><span class="team-check">${icon('check')}</span></div><h3>${t==='Leave'?'A full team. A good night.':t==='Birthdays'?'Make room for a little celebration.':'Another year, more possibilities.'}</h3><p>${t==='Leave'?"No approved leave recorded for today.":t==='Birthdays'?'Birthday tracking is not configured.':'Anniversary tracking is not configured.'}</p>`;}
function shiftCard(){const d=S.dashboard,active=d.state==='checked_in',done=d.state==='checked_out';return `<section class="card shift-card"><div class="shift-card-head"><span class="shift-icon">${icon('moon')}</span><div><h2>Your night shift</h2><p>INDIA STANDARD TIME</p></div><button class="icon-button" data-action="shift-settings" aria-label="Edit night-shift schedule">${icon('settings')}</button></div><div class="shift-hours"><strong>${time12(d.shift.start_time)}</strong><span>${icon('arrowright')}</span><strong>${time12(d.shift.end_time)}</strong></div><div class="shift-date-line">${fmt(d.scheduled_start)} <span>to ${fmt(d.scheduled_end)} &middot; ${duration(d.shift.duration_seconds,false).slice(0,-3)} hours</span></div><div class="shift-session"><span class="session-state ${active?'is-active':''}"><i></i>${active?'Checked in &middot; shift in progress':done?'Shift complete &middot; attendance saved':'Ready when you are'}</span><strong id="work-clock">${duration(d.today?.worked_seconds||0)}</strong><small>HOURS LOGGED THIS SHIFT</small></div><button class="checkin-button ${active?'checkout':''}" data-action="punch">${icon(active?'logout':done?'checkcircle':'login')} ${checkLabel(d)} ${icon('arrowright')}</button><div class="checkin-details"><span>${active||done?'Checked in at '+clock12(d.today?.clock_in):'Check in to start your work timer'}</span>${done?`<span>Out ${clock12(d.today.clock_out)}</span>`:'<span class="secure-tag">'+icon('shield')+' Local</span>'}</div><div class="shift-live"><span class="live-dot"></span>IST now <span id="ist-clock">${clock12(d.server_time)}</span><button data-nav="time">View attendance ${icon('chevron')}</button></div></section>`;}
async function dashboardPage(){
 await loadMetrics();const d=S.dashboard,earned=S.balances.find(b=>b.type==='Earned Leave'),worked=S.metrics.total_worked??S.metrics.chart.reduce((n,r)=>n+r.worked_seconds,0);
 return `<div class="workspace-heading"><div><span class="eyebrow blue-ink">YOUR WORKSPACE, CONNECTED</span><h1>Hello, ${esc(S.user.first_name)}<span class="greeting-dot">.</span></h1><p>Everything you need for a great night at work.</p></div><div class="workspace-date">${icon('calendar')}<span>${fmt(d.server_time,'full')}<small>Night-shift workspace &middot; IST</small></span></div></div>
 <div class="dashboard-grid"><div class="dashboard-left"><section class="night-hero"><div class="hero-copy"><span class="hero-pill">${icon('moon')} MADE FOR YOUR NIGHT SHIFT</span><h2>Great work.<br>Beyond daylight.</h2><p>Your people, your progress and your next possibility.<br>All together in one workspace.</p><button class="hero-link" data-nav="time">Your shift, at a glance ${icon('arrowright')}</button></div><div class="hero-orbit" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><span class="orbit-star s1"></span><span class="orbit-star s2"></span><span class="orbit-star s3"></span><div class="orb-globe"><div class="globe-meridian m1"></div><div class="globe-meridian m2"></div><div class="globe-latitude l1"></div><div class="globe-latitude l2"></div><div class="globe-latitude l3"></div></div><div class="orbit-badge">${icon('moon')}<span>AFTER HOURS.<br><b>ALWAYS CONNECTED.</b></span></div></div></section>
 <div class="workspace-stats">${[[icon('tasks'),d.tasks.length,'Open tasks','tasks'],[icon('leave'),(earned?.balance??0)+'<small> days</small>','Earned leave','time'],[icon('clock'),Math.floor(worked/3600)+'<small>h '+Math.floor(worked%3600/60)+'m</small>','Last 7 completed dates','time']].map(([i,v,l,to])=>`<button class="card workspace-stat" data-nav="${to}"><span class="stat-symbol">${i}</span><span><strong>${v}</strong><small>${l}</small></span>${icon('chevron')}</button>`).join('')}</div>
 <section class="card priorities-card"><div class="card-heading"><div><h2>Your priorities <span class="count-pill">${d.tasks.length}</span></h2><p class="section-subtitle">A little focus. A lot of progress.</p></div><button class="link-button" data-nav="tasks">View all tasks ${icon('chevron')}</button></div>${d.tasks.slice(0,2).map(t=>`<button class="task-row" data-action="task" data-id="${t.id}"><span class="task-symbol">${icon(t.id===2?'target':'tasks')}</span><div class="task-text"><strong>${esc(t.title)}</strong><div class="tiny">${esc(t.flow)} &middot; Due ${fmt(t.due_date)}</div></div><span class="badge pending">Pending</span>${icon('chevron')}</button>`).join('')||'<div class="empty-state">All caught up. Enjoy a fresh start.</div>'}</section>
 <section class="card recent-card"><div class="card-heading"><h2>Your everyday essentials</h2><button class="link-button" data-action="apps">All Apps ${icon('grid')}</button></div><div class="recent-apps">${['payslips','documents','profile','time',...(S.user.role==='admin'?['employees','document-centre']:['it','admin-services']),'performance','learn'].map(id=>`<button class="recent-app" data-nav="${id}">${appImg(id,false)}<span>${esc(app(id).name)}</span></button>`).join('')}</div></section>
 </div><aside class="dashboard-right">${shiftCard()}<section class="card requests-card"><div class="card-heading"><h2>Make a request</h2><button class="link-button" data-nav="flows">View all</button></div><div class="request-grid"><button class="request-tile" data-action="leave">${icon('leave')}<span>Apply for leave</span>${icon('chevron')}</button><button class="request-tile" data-action="request" data-kind="regularization">${icon('clock')}<span>Fix attendance</span>${icon('chevron')}</button><button class="request-tile" data-action="request" data-kind="expense">${icon('wallet')}<span>Claim an expense</span>${icon('chevron')}</button><button class="request-tile" data-action="request" data-kind="letter">${icon('document')}<span>Request a letter</span>${icon('chevron')}</button></div></section><section class="card events-card"><div class="card-heading"><h2>Around your team</h2>${icon('users')}</div><div class="event-tabs">${['Leave','Birthdays','Anniversaries'].map(t=>`<button class="${t===S.eventTab?'active':''}" data-action="event" data-tab="${t}">${t}</button>`).join('')}</div><div class="event-content" id="events-content">${eventHTML()}</div></section></aside></div>
 <div class="section-divider"><span>YOUR TIME &amp; WELLBEING</span><button class="link-button" data-nav="time">Open Time &amp; Attendance ${icon('arrowright')}</button></div><div class="metrics-layout">${metricsHTML()}${balancesHTML()}</div>`;
}
function updateClock(){if(!S.dashboard)return;const current=Date.parse(S.dashboard.server_time)+(Date.now()-(S.clockSync||Date.now())),r=S.dashboard.today;const e=$('#work-clock');if(e)e.textContent=duration(r?.clock_in&&!r.clock_out?(current-Date.parse(r.clock_in))/1000:r?.worked_seconds||0);const nowEl=$('#ist-clock');if(nowEl)nowEl.textContent=clock12(new Date(current).toISOString());}
setInterval(updateClock,1000);
async function tasksPage(){S.tasks=await api('/tasks');return `${heading('My Tasks','Manage the things that need your attention.',`<span class="switch-row">Saved Filters <button class="switch ${localStore.getItem('portal-filters')?'on':''}" data-action="save-filters" role="switch" aria-checked="${!!localStore.getItem('portal-filters')}"></button></span>`)}<section class="card section-card"><div class="tabs">${[['my','My Action Items'],['goals','Goal Tasks'],['completed','Completed'],['all','All Tasks']].map(([id,label])=>`<button class="tab ${S.taskTab===id?'active':''}" data-action="task-tab" data-tab="${id}">${label}</button>`).join('')}</div><div class="toolbar"><div class="field-search"><input id="task-search" value="${esc(S.taskQ)}" placeholder="Search by task or flow name" aria-label="Search tasks">${icon('search')}</div><div class="row"><button class="button small" data-action="task-filters" aria-label="Filter tasks">${icon('filter')}</button><button class="button small" data-action="task-settings" aria-label="Task table settings">${icon('settings')}</button></div></div>${S.filters?`<div class="filter-bar"><label>Status <select id="task-status"><option value="">Any status</option>${['Pending','Completed'].map(s=>`<option ${S.taskStatus===s?'selected':''}>${s}</option>`).join('')}</select></label><button class="link-button" data-action="clear-filters">Clear filters</button></div>`:''}<div id="task-table"></div></section>`;}
function taskTable(){const q=S.taskQ.toLowerCase();let data=S.tasks.filter(t=>(S.taskTab==='all'||S.taskTab==='my'&&t.id!==2&&t.status==='Pending'||S.taskTab==='goals'&&t.id===2&&t.status==='Pending'||S.taskTab==='completed'&&t.status==='Completed')&&(!S.taskStatus||t.status===S.taskStatus)&&(!q||(t.title+' '+t.flow+' '+t.reference).toLowerCase().includes(q))).sort((a,b)=>S.ascending?a.due_date.localeCompare(b.due_date):b.due_date.localeCompare(a.due_date));const pages=Math.max(1,Math.ceil(data.length/S.taskSize));S.taskPage=Math.max(1,Math.min(S.taskPage,pages));const shown=data.slice((S.taskPage-1)*S.taskSize,S.taskPage*S.taskSize);$('#task-table').innerHTML=shown.length?`<div class="table-wrapper"><table><thead><tr><th>Requested For</th><th>Workflow Stage Name</th><th>Flow Name</th><th>Trigger Date</th><th><button data-action="task-sort" style="padding:0">Due Date &nbsp; ${S.ascending?'\u2191':'\u2193'}</button></th><th>Actions</th></tr></thead><tbody>${shown.map(t=>`<tr><td><div class="row">${avatar()}<div><button class="primary-link" data-nav="profile">${esc(S.user.first_name)} .</button><span class="secondary">${esc(S.user.employee_id)}</span></div></div></td><td>${esc(t.title)}<span class="secondary">${esc(t.stage)}</span></td><td><button class="primary-link" data-action="task" data-id="${t.id}">${esc(t.flow)}</button><span class="secondary">${esc(t.reference)}</span></td><td>${fmt(t.trigger_date,'numeric')}</td><td>${fmt(t.due_date,'numeric')}<span class="secondary">${t.status==='Completed'?badge('Completed'):new Date(t.due_date)<new Date()?'<span class="badge overdue" style="border-left:3px solid #e73c68">Overdue</span>':badge('Pending')}</span></td><td><button class="task-act" data-action="task" data-id="${t.id}">${t.status==='Completed'?'View':'Act'}</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${data.length} Records</span><div class="pagination"><button class="icon-button" data-action="task-prev" aria-label="Previous page" ${S.taskPage<=1?'disabled':''}>${icon('arrow')}</button><span class="page-number">${S.taskPage}</span><button class="icon-button" data-action="task-next" aria-label="Next page" ${S.taskPage>=pages?'disabled':''}>${icon('chevron')}</button></div><span><select class="table-size" id="task-size" aria-label="Tasks per page">${[10,20,50].map(n=>`<option ${S.taskSize===n?'selected':''}>${n}</option>`).join('')}</select> per page</span></div>`:empty('No tasks to show','There are no tasks matching this view. Try another tab or clear the filters.');}
async function timePage(){await loadMetrics();const leaves=await api('/leaves'),d=S.dashboard;return `${heading('Time & Attendance','A clear view of your night shift. From check in to check out.',btn('Edit Night Shift','shift-settings','settings')+btn('Apply Leave','leave','plus',true))}<div class="time-summary">${shiftCard()}<section class="card shift-explainer"><span class="eyebrow blue-ink">YOUR OVERNIGHT SCHEDULE</span><h2>One night.<br>One attendance record.</h2><p>Your shift begins at <strong>${time12(d.shift.start_time)}</strong> and ends at <strong>${time12(d.shift.end_time)}</strong> the following morning. Checking out after midnight completes the same record.</p><div class="schedule-track"><span>${icon('moon')}<b>${time12(d.shift.start_time)}</b><small>Shift starts</small></span><i></i><span>${icon('sun')}<b>${time12(d.shift.end_time)}</b><small>Next morning</small></span></div><div class="notice blue">Early check-in is allowed. Actual server time is recorded in IST. Confirm your assigned working hours with your administrator.</div><button class="link-button" data-action="request" data-kind="regularization">Request an attendance correction ${icon('arrowright')}</button></section></div><div class="metrics-layout">${metricsHTML()}${balancesHTML()}</div><section class="card section-card attendance-history"><div class="card-heading"><div><h2>Attendance history</h2><p class="section-subtitle">Grouped by the date your night shift begins</p></div><div class="row wrap"><label class="small muted" for="attendance-end">Chart ending</label><input type="date" id="attendance-end" value="${S.metrics.end}"><a class="button small" href="/api/attendance/export">${icon('download')}Export CSV</a></div></div><div class="table-wrapper"><table><thead><tr><th>Shift date</th><th>Check In (IST)</th><th>Check Out (IST)</th><th>Work duration</th><th>Late arrival</th><th>Notes</th></tr></thead><tbody>${S.metrics.history.map(r=>`<tr><td>${fmt(r.date,'full')}</td><td>${clock12(r.clock_in)}${r.clock_in?`<small class="cell-date">${fmt(r.clock_in)}</small>`:''}</td><td>${r.clock_out?`${clock12(r.clock_out)}<small class="cell-date">${fmt(r.clock_out)}</small>`:'--'}</td><td>${r.clock_in&&!r.clock_out?badge('Checked in'):duration(r.worked_seconds)}</td><td>${duration(r.late_seconds)}</td><td class="muted">${esc(r.note||'--')}</td></tr>`).join('')||'<tr><td colspan="6">No attendance recorded yet. Check in to get started.</td></tr>'}</tbody></table></div></section><section class="card section-card leave-history"><div class="card-heading"><h2>My leave requests</h2><button class="link-button" data-action="leave">Apply leave</button></div>${leaves.length?`<div class="table-wrapper"><table><thead><tr><th>Leave type</th><th>Dates</th><th>Days</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>${leaves.map(l=>`<tr><td>${esc(l.type)}</td><td>${fmt(l.start_date)} &ndash; ${fmt(l.end_date,'full')}</td><td>${l.days}</td><td><p>${esc(l.reason)}</p>${l.review_note?`<span class="secondary">Admin: ${esc(l.review_note)}</span>`:''}</td><td>${badge(l.status)}</td><td>${['Pending','Approved'].includes(l.status)?`<button class="link-button" data-action="cancel-leave" data-id="${l.id}">Cancel</button>`:'--'}</td></tr>`).join('')}</tbody></table></div>`:empty('No leave requests yet','Your applications and approval status will appear here.')}</section>`;}
function profilePage(){const u=S.user;return `${heading('My Profile','Your information, always up to date.')}<div class="profile-layout"><aside class="card profile-summary"><div class="profile-photo-wrap">${u.photo_url?`<img class="profile-photo" src="${esc(u.photo_url)}" alt="Profile photo">`:`<div class="initials profile-initials">${esc((u.first_name[0]||'')+(u.last_name[0]||''))}</div>`}<label class="button small photo-upload"><input id="profile-photo-file" type="file" accept="image/jpeg,image/png,image/webp" hidden>Change photo</label></div><h2>${esc(u.first_name+' '+u.last_name)}</h2><p>${esc(u.designation)}</p><span class="profile-id">${esc(u.employee_id)}</span><p>${esc(u.department)}</p><hr><p>${icon('pin')} ${esc(u.location)}</p><p style="margin-top:14px">${icon('mail')} ${esc(u.email)}</p><div class="notice" style="margin:24px 0 0;font-size:10px">Your workspace account.<br>Contact an administrator to update account or role details.</div></aside><section class="card section-card"><div class="card-heading"><h2>Personal Details</h2>${badge(u.role==='admin'?'Admin':'Employee')}</div><form data-form="profile"><div class="form-grid">${field('First Name','first_name','text',u.first_name,'required maxlength="60"')}${field('Last Name','last_name','text',u.last_name,'maxlength="60"')}${field('Email Address','email','email',u.email,'readonly')}${field('Employee ID','employee_id','text',u.employee_id,'readonly')}${field('Phone Number','phone','tel',u.phone,'maxlength="24"')}${field('Location','location','text',u.location,'required maxlength="100"')}${field('Department','department','text',u.department,'readonly')}${field('Designation','designation','text',u.designation,'readonly')}${field('Reporting Manager','manager','text',u.manager,'readonly')}${field('Date of Joining','joined','text',fmt(u.joined,'full'),'readonly')}</div><p class="error-text" role="alert"></p><div class="form-actions"><button type="button" class="button" data-action="preferences">Preferences</button><button type="submit" class="button primary">Save Changes</button></div></form></section></div>`;}
async function membersPage(){S.members=await api('/members');return `${heading('Members','Connect with the people in your organization.')}<div class="toolbar"><div class="field-search"><input id="member-search" placeholder="Search name, department or employee ID" aria-label="Search members">${icon('search')}</div><span class="small muted">${S.members.length} team members</span></div><div class="member-grid" id="member-grid">${memberCards(S.members)}</div>`;}
function memberCards(data){return data.length?data.map(u=>`<article class="card member-card">${u.photo_url?`<img class="member-photo" src="${esc(u.photo_url)}" alt="Profile photo">`:`<div class="initials">${esc(u.first_name[0]+(u.last_name[0]||''))}</div>`}<h3>${esc(u.first_name+' '+u.last_name)}</h3><p class="small muted" style="margin-top:4px">${esc(u.designation)}</p><p class="department">${esc(u.department)}</p><div class="info">${icon('mail')} ${esc(u.email)}</div><div class="info">${icon('pin')} ${esc(u.location)}</div><div class="info">${icon('user')} ${esc(u.employee_id)}</div><button class="link-button" style="margin-top:12px" data-action="member" data-id="${u.id}">View details ${icon('chevron')}</button></article>`).join(''):empty('No matching people','Try another name or department.');}
async function goalsPage(){S.goals=await api('/goals');const goals=S.goals,avg=goals.length?Math.round(goals.reduce((s,g)=>s+g.progress,0)/goals.length):0;return `${heading('Performance','Turn your goals into meaningful progress.',btn('Add Goal','goal','plus',true))}<div class="mini-kpis">${[['Total goals',goals.length],['In progress',goals.filter(g=>g.progress>0&&g.progress<100).length],['Completed',goals.filter(g=>g.progress===100).length],['Overall progress',avg+'%']].map(([l,v])=>`<div class="card mini-kpi"><p>${l}</p><b>${v}</b></div>`).join('')}</div>${goals.length?`<div class="goal-grid">${goals.map(g=>`<article class="card goal-card"><div class="between">${icon('target')}<button class="icon-button" data-action="delete-goal" data-id="${g.id}" aria-label="Delete goal">${icon('trash')}</button></div><h3 style="margin-top:14px">${esc(g.title)}</h3><p>${esc(g.description||'Keep taking the next small step toward your goal.')}</p><div class="between tiny muted"><span>Due ${fmt(g.target_date,'full')}</span><b>${g.progress}%</b></div><div class="progress-track"><span style="width:${g.progress}%"></span></div><button class="button small" data-action="progress" data-id="${g.id}">Update Progress</button></article>`).join('')}</div>`:`<div class="card">${empty('Your next milestone starts here','Add a goal with a target date and track measurable progress.',btn('Add your first goal','goal','plus',true))}</div>`}`;}
async function jobsPage(){S.jobs=await api('/jobs');return `${heading('Recruitment','Discover opportunities. Refer great people.',btn('Submit a Referral','request','plus',true,'data-kind="referral"'))}<div class="notice blue">No recruitment service is connected. Referrals are saved for administrator review.</div><div class="toolbar"><div class="field-search"><input id="job-search" placeholder="Search role, department or location" aria-label="Search jobs">${icon('search')}</div><span class="small muted">${S.jobs.length} openings</span></div><div class="job-grid" id="job-grid">${jobCards(S.jobs)}</div>`;}
function jobCards(data){return data.length?data.map(j=>`<article class="card job-card"><div class="row muted" style="margin-bottom:14px">${icon('briefcase')}<span class="tiny">JOB-${String(j.id).padStart(4,'0')}</span></div><h3>${esc(j.title)}</h3><p class="small muted" style="margin-top:5px">${esc(j.department)}</p><div class="tag-line"><span class="badge">${esc(j.location)}</span><span class="badge">${esc(j.type)}</span></div><button class="button small" data-action="request" data-kind="referral" data-title="${esc(j.title)}">Refer someone ${icon('chevron')}</button></article>`).join(''):empty('No matching openings','Try a broader search.');}
async function ticketsPage(){const a=app(S.route),data=await api('/tickets');return `${heading(a.name,'Get the help you need, without the back-and-forth.',btn('Raise a Ticket','ticket','plus',true,`data-category="${a.name}"`))}<div class="card module-banner">${appImg(S.route)}<div><h2>How can we help you?</h2><p>Raise a request, track progress, and view administrator responses. These tickets are stored in your local database.</p></div></div><section class="card section-card"><div class="card-heading"><h2>My Support Tickets</h2><span class="small muted">${data.length} tickets</span></div>${data.length?`<div class="table-wrapper"><table><thead><tr><th>Ticket</th><th>Category</th><th>Priority</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${data.map(t=>`<tr><td><button class="primary-link" data-action="ticket-detail" data-id="${t.id}">${esc(t.title)}</button><span class="secondary">TKT-${String(t.id).padStart(4,'0')}</span></td><td>${esc(t.category)}</td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td><td>${fmt(t.created_at,'full')}</td><td><button class="link-button" data-action="ticket-detail" data-id="${t.id}">View</button></td></tr>`).join('')}</tbody></table></div>`:empty('No tickets yet','Create a local support ticket and the administrator can respond.',btn('Raise a Ticket','ticket','plus',true,`data-category="${a.name}"`))}</section>`;}
const requestTitles={flow:'Initiate Flow',letter:'Request Letter',expense:'New Reimbursement',travel:'Travel Request',referral:'Refer a Candidate',service:'Service Request',regularization:'Regularize Attendance',tax:'Tax Declaration Request'};
async function requestsPage(kind=''){S.requests=await api('/requests'+(kind?'?kind='+kind:''));const data=S.requests,title=kind==='letter'?'HR Documents':kind==='expense'?'Expenses':kind==='travel'?'Travel desk':'Flows & Requests';return `${heading(title,'Submit requests and follow their local approval status.',btn(kind?requestTitles[kind]:'Initiate Flow','request','plus',true,`data-kind="${kind||'flow'}"`))}${kind==='letter'?'<div class="notice warning">Submit a document request for HR review. Published offer letters and payslips appear in My Documents.</div>':kind==='expense'?'<div class="notice blue">Approval does not trigger a payment or connect to payroll.</div>':kind==='travel'?'<div class="notice blue">Travel requests require administrative review. No booking service is connected.</div>':''}${!kind?`<div class="service-grid" style="margin-bottom:22px">${[['flow','Initiate Flow','Start a local HR workflow','flow'],['letter','Request Letter','Ask HR for a document','document'],['expense','Reimbursement','Submit an expense for review','wallet']].map(([k,t,p,ic])=>`<button class="card service-tile" data-action="request" data-kind="${k}">${icon(ic)}<div><h3>${t}</h3><p>${p}</p></div></button>`).join('')}</div>`:''}<section class="card section-card"><div class="card-heading"><h2>My Requests</h2><span class="small muted">${data.length} requests</span></div>${data.length?`<div class="table-wrapper"><table><thead><tr><th>Reference / Title</th><th>Type</th><th>Submitted</th><th>Status</th><th>Actions</th></tr></thead><tbody>${data.map(r=>`<tr><td><button class="primary-link" data-action="request-detail" data-id="${r.id}">${esc(r.title)}</button><span class="secondary">REQ-${String(r.id).padStart(4,'0')}${r.kind==='expense'?' \u00b7 INR '+Number(r.details.amount).toLocaleString('en-IN'):''}</span></td><td style="text-transform:capitalize">${esc(r.kind)}</td><td>${fmt(r.created_at,'full')}</td><td>${badge(r.status)}</td><td><button class="link-button" data-action="request-detail" data-id="${r.id}">View Details</button></td></tr>`).join('')}</tbody></table></div>`:empty('Your requests will appear here','Submit a request to start a real local workflow. An administrator can approve or reject it.')}</section>`;}
function policiesPage(){return workspacePoliciesV3();}
async function orgPage(){return organizationPageV3();}
async function postsPage(){const data=await api('/posts');return `${heading('Vibe','Small updates. Stronger connections.')}<form class="card post-form" data-form="post" style="max-width:900px"><div class="row">${avatar()}<h3>Share something with your team</h3></div><textarea name="body" placeholder="A team update, a thank you, or a small win..." required minlength="3" maxlength="2000" aria-label="Your team update"></textarea><p class="error-text" role="alert"></p><div class="between"><span class="tiny muted">Visible to signed-in colleagues.</span><button type="submit" class="button primary">Share Update</button></div></form>${data.map(p=>`<article class="card post-card"><div class="between"><div class="row">${avatar({...p,id:p.user_id})}<div><h3 style="font-size:12px">${esc(p.first_name+' '+p.last_name)}</h3><span class="tiny muted">${esc(p.department)}</span></div></div><span class="tiny muted">${fmt(p.created_at,'full')}</span></div><div class="post-body">${esc(p.body)}</div></article>`).join('')}`;}
function servicePage(){const a=app(S.route),pay=S.route==='compensation';return `${heading(a.name,'Your local service workspace.')}<section class="card module-banner">${appImg(S.route)}<div><h2>${esc(a.name)}</h2><p>${pay?'No payroll or bank account is connected. Payroll calculation is not connected.':'Your independent local service workspace. No external account or service is connected.'}</p></div>${btn('Create Request','request','plus',true,`data-kind="${pay?'letter':'service'}" data-title="${pay?'Salary certificate':esc(a.name)+' request'}"`)}</section><div class="notice blue">Third-party benefits, financial services and course platforms require authorized integrations. This replica does not impersonate their sign-in pages or make external transactions.</div><div class="service-grid"><button class="card service-tile" data-action="request" data-kind="service" data-title="${esc(a.name)} request">${icon('plus')}<div><h3>Request Assistance</h3><p>Save a local service request.</p></div></button><button class="card service-tile" data-nav="flows">${icon('flow')}<div><h3>Track My Requests</h3><p>View status and admin responses.</p></div></button>${pay?`<button class="card service-tile" data-nav="expenses">${icon('money')}<div><h3>Reimbursements</h3><p>Manage your expense requests.</p></div></button>`:''}</div>`;}
async function adminAttendancePage(){
 if(S.user.role!=='admin')return `${heading('Attendance Management')}<div class="card">${empty('Administrator access required','Sign in with an administrator account to manage employee attendance.')}</div>`;
 S.employees=await api('/admin/employees');
 const active=S.employees.filter(e=>e.is_active);
 if(!active.length)return `${heading('Attendance Management','Choose an employee and update the previous 14 completed shift dates.')}<div class="card">${empty('No employees yet','Create an employee account first from Employee Accounts.')}</div>`;
 S.adminAttendanceEmployee=Number(S.adminAttendanceEmployee||active[0].id);
 if(!active.some(e=>e.id===S.adminAttendanceEmployee))S.adminAttendanceEmployee=active[0].id;
 const data=await api('/admin/attendance/'+S.adminAttendanceEmployee);
 const map=Object.fromEntries(data.records.map(r=>[r.date,r]));
 const start=new Date(data.start+'T12:00:00+05:30');
 const end=new Date(data.end+'T12:00:00+05:30');
 const days=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const key=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata'}).format(d);days.push(key);}
 const cells=days.map(day=>{const r=map[day];const status=r?.clock_in?'Present':r?.off_seconds?'Off':'Not set';return `<button class="attendance-admin-day ${r?.clock_in?'present':r?.off_seconds?'off':'empty'}" data-action="edit-admin-attendance" data-date="${day}"><span>${new Date(day+'T12:00:00').getDate()}</span><b>${status}</b><small>${r?.clock_in?`${clock12(r.clock_in)} – ${clock12(r.clock_out)}`:r?.off_seconds?'Weekly off / leave':'Click to update'}</small></button>`;}).join('');
 const selected=active.find(e=>e.id===S.adminAttendanceEmployee);
 return `${heading('Attendance Management','Use the calendar to update any employee for the previous 14 completed shift dates.',btn('Refresh','refresh','clock'))}<section class="card section-card"><div class="admin-attendance-toolbar"><div class="field" style="min-width:280px"><label for="admin-attendance-employee">Employee</label><select id="admin-attendance-employee">${active.map(e=>`<option value="${e.id}" ${e.id===S.adminAttendanceEmployee?'selected':''}>${esc(e.first_name+' '+e.last_name)} · ${esc(e.employee_id)}</option>`).join('')}</select></div><div class="admin-attendance-range"><strong>${fmt(data.start,'full')} – ${fmt(data.end,'full')}</strong><span>14 completed shift dates · IST</span></div></div><div class="notice blue">Click any date to enter or correct check-in and check-out times. Changes are saved directly to the employee's attendance record.</div><div class="attendance-admin-calendar">${cells}</div><div class="attendance-admin-legend"><span><i class="present-dot"></i> Present</span><span><i class="off-dot"></i> Off / leave</span><span><i class="empty-dot"></i> Not set</span></div></section><section class="card section-card"><div class="card-heading"><div><h2>${esc(selected.first_name+' '+selected.last_name)}</h2><p class="section-subtitle">${esc(selected.employee_id)} · ${esc(selected.email)}</p></div><span class="badge">Admin editable</span></div><div class="table-wrapper"><table><thead><tr><th>Date</th><th>Check in</th><th>Check out</th><th>Worked</th><th>Late</th><th>Notes</th><th></th></tr></thead><tbody>${days.map(day=>{const r=map[day];return `<tr><td>${fmt(day,'full')}</td><td>${r?.clock_in?clock12(r.clock_in):'—'}</td><td>${r?.clock_out?clock12(r.clock_out):'—'}</td><td>${r?.clock_in?duration(r.worked_seconds):'—'}</td><td>${r?.clock_in?duration(r.late_seconds):'—'}</td><td>${esc(r?.note||'—')}</td><td><button class="link-button" data-action="edit-admin-attendance" data-date="${day}">Edit</button></td></tr>`;}).join('')}</tbody></table></div></section>`;
}
function editAdminAttendance(dateValue){
 const uid=Number(S.adminAttendanceEmployee);api('/admin/attendance/'+uid).then(data=>{
  const r=data.records.find(x=>x.date===dateValue);const present=!!r?.clock_in;const shift=data.shift;
  modal('Update attendance',`<form data-form="admin-attendance" data-user-id="${uid}"><input type="hidden" name="date" value="${dateValue}"><div class="notice blue"><strong>${fmt(dateValue,'full')}</strong><br>${esc(data.employee.first_name+' '+data.employee.last_name)} · ${esc(data.employee.employee_id)}<br>Allowed range: ${fmt(data.start)} – ${fmt(data.end)}. Times use IST.</div><div class="field"><label for="admin-attendance-status">Attendance status</label><select id="admin-attendance-status" name="status"><option value="present" ${present?'selected':''}>Present</option><option value="off" ${!present?'selected':''}>Off / leave</option></select></div><div class="form-grid" id="admin-attendance-times">${field('Check In','clock_in','time',present?clock24(r.clock_in):shift.start_time,'required')}${field('Check Out','clock_out','time',present?clock24(r.clock_out):shift.end_time,'required')}</div>${area('Note','note',r?.note||'Administrator attendance update.')}<p class="tiny muted">For the overnight shift, a check-out after midnight belongs to this shift date.</p>${actions('Save Attendance')}</form>`);
 }).catch(e=>toast(e.message,true));
}
function clock24(v){return v?new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Kolkata'}).format(new Date(v)):'';}
async function regularizePage(){return `${heading('Regularize Attendance','Submit a correction when your check-in or check-out was missed or recorded incorrectly.',btn('Back to Attendance','nav-time','clock'))}<section class="card section-card"><div class="empty-state"><div class="empty-icon">${icon('clock')}</div><h3>Attendance correction</h3><p>Use this form to request a correction for a previous shift. Your request will be sent to the administrator for approval.</p><button class="button primary" data-action="request" data-kind="regularization">Regularize Attendance</button></div></section>`;}
async function attendanceRequestsPage(){if(S.user.role!=='admin')return empty('Administrator access required','Sign in with an administrator account to review attendance corrections.');const d=await api('/admin/overview');S.overview=d;const data=(d.requests||[]).filter(r=>r.kind==='regularization');return `${heading('Regularize Requests','Review employee attendance correction requests and approve them to update attendance automatically.',btn('Attendance Edit','nav-attendance-edit','calendar'))}<div class="mini-kpis"><div class="card mini-kpi"><p>Pending regularizations</p><b>${data.filter(r=>r.status==='Pending').length}</b></div><div class="card mini-kpi"><p>Total requests</p><b>${data.length}</b></div></div><section class="card section-card"><div class="table-wrapper"><table><thead><tr><th>Employee</th><th>Shift Date</th><th>Requested Time</th><th>Reason</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.length?data.map(r=>{const d=r.details||{};return `<tr><td>${esc(r.first_name+' '+r.last_name)}<span class="secondary">${esc(r.employee_id)}</span></td><td>${esc(d.date||'—')}</td><td>${esc(d.clock_in||'—')} – ${esc(d.clock_out||'—')}</td><td>${esc(d.reason||'—')}</td><td>${badge(r.status)}</td><td><button class="button small" data-action="review" data-kind="requests" data-id="${r.id}">${r.status==='Pending'?'Review':'View'}</button></td></tr>`}).join(''):'<tr><td colspan="6">No attendance regularization requests found.</td></tr>'}</tbody></table></div></section>`;}
async function adminPage(){if(S.user.role!=='admin')return `${heading('Admin Review')}<div class="card">${empty('Administrator access required','Sign in with an administrator account to review requests. Employees cannot access administration data.',btn('Switch Account','sign-out','user',true))}</div>`;S.overview=await api('/admin/overview');const d=S.overview;return `${heading('Admin Review','Review local requests, resolve tickets, and keep an audit trail.')}<div class="notice">Manage approvals here. Use Employee Accounts and Document Centre to provision access and publish files.</div><div class="mini-kpis">${[['Pending leave requests',d.leaves.filter(x=>x.status==='Pending').length],['Open support tickets',d.tickets.filter(x=>x.status!=='Resolved').length],['Pending requests',d.requests.filter(x=>x.status==='Pending').length],['Recent audit entries',d.audit.length]].map(([l,v])=>`<div class="card mini-kpi"><p>${l}</p><b>${v}</b></div>`).join('')}</div><section class="card section-card"><div class="tabs">${[['leaves','Leave Requests'],['tickets','Support Tickets'],['requests','Other Requests'],['audit','Audit Trail']].map(([id,t])=>`<button class="tab ${S.adminTab===id?'active':''}" data-action="admin-tab" data-tab="${id}">${t}<span class="count">${d[id].length}</span></button>`).join('')}</div><div id="admin-table"></div></section>`;}
function adminTable(){const kind=S.adminTab,data=S.overview[kind];if(!data.length){$('#admin-table').innerHTML=empty('Nothing awaiting review','Requests submitted by the employee will appear here.');return;}if(kind==='audit'){$('#admin-table').innerHTML=`<div class="table-wrapper"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody>${data.map(r=>`<tr><td>${fmt(r.created_at)} ${clock(r.created_at)}</td><td>${esc((r.first_name||'System')+' '+(r.last_name||''))}</td><td>${esc(r.action)}</td><td>${esc(r.entity)} ${r.entity_id||''}</td><td>${esc(r.detail||'\u2014')}</td></tr>`).join('')}</tbody></table></div>`;return;}$('#admin-table').innerHTML=`<div class="table-wrapper"><table><thead><tr><th>Employee</th><th>${kind==='leaves'?'Leave Type / Dates':'Request'}</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.map(r=>`<tr><td>${esc(r.first_name+' '+r.last_name)}<span class="secondary">${esc(r.employee_id)}</span></td><td>${esc(kind==='leaves'?r.type:r.title)}<span class="secondary">${kind==='leaves'?`${fmt(r.start_date)} - ${fmt(r.end_date,'full')} \u00b7 ${r.days} day(s)`:esc(kind==='tickets'?r.category:r.kind)}</span></td><td><p>${esc(kind==='leaves'?r.reason:kind==='tickets'?r.description:r.details?.reason||r.details?.purpose||r.details?.description||'Open to review all details.')}</p></td><td>${badge(r.status)}</td><td><button class="button small" data-action="review" data-kind="${kind}" data-id="${r.id}">${r.status==='Pending'||kind==='tickets'?'Review':'View'}</button></td></tr>`).join('')}</tbody></table></div>`;}
function openApps(){closeOverlays();$('#overlay-root').innerHTML=`<div class="drawer-shade" data-action="close-overlays"></div><aside class="app-drawer" aria-label="All Apps menu"><div class="drawer-search-row"><button class="icon-button" data-action="close-overlays" aria-label="Close All Apps">${icon('arrow')}</button><div class="drawer-search"><input id="app-search" placeholder="All Apps" aria-label="Search all apps" autocomplete="off">${icon('search')}</div></div><div id="drawer-results"></div><p class="drawer-note">Colleague workspace \u00b7 Account access</p></aside>`;appGrid('');document.body.style.overflow='hidden';$('#app-search').focus();}
function appGrid(query){const q=query.toLowerCase().trim(),all=[...APPS.filter(a=>S.user.role==='admin'||!['employees','document-centre'].includes(a.id)),...(S.user.role==='admin'?[{id:'admin',name:'Admin Review'}]:[])].filter(a=>a.name.toLowerCase().includes(q)),recent=['tasks','it','admin-services','travel','benefits','refyne','learn','time'].map(app).filter(a=>a.name.toLowerCase().includes(q));const tile=a=>`<button class="drawer-app" data-nav="${a.id}">${appImg(a.id==='admin'?'policies':a.id)}<span>${esc(a.name)}</span></button>`;$('#drawer-results').innerHTML=`${recent.length?`<h2>Recent Apps</h2><div class="drawer-grid">${recent.map(tile).join('')}</div>`:''}<h2 class="all-apps-heading">All Apps</h2><div class="drawer-grid">${all.map(tile).join('')}</div>${all.length?'':'<p class="no-match">No matching apps.</p>'}`;}
function accountMenu(){accountMenuV3();}
async function notifications(){closeOverlays();const data=await api('/notifications');$('#overlay-root').innerHTML=`<div class="popover notification-popover"><div class="popover-header between"><strong>Notifications</strong><button class="link-button" data-action="read-notifications">Mark all as read</button></div>${data.map(n=>`<button class="notification-item ${n.is_read?'read':'unread'}" data-nav="${esc(n.target)}"><i class="status-dot"></i><div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div></button>`).join('')||'<p class="no-match">No notifications.</p>'}</div>`;}
function details(d){return `<dl class="detail-grid">${Object.entries(d||{}).map(([k,v])=>`<div><dt style="text-transform:capitalize">${esc(k.replaceAll('_',' '))}</dt><dd style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(typeof v==='object'?JSON.stringify(v):v||'\u2014')}</dd></div>`).join('')}</dl>`;}
async function openTask(id){const data=await api('/tasks'),t=data.find(x=>x.id===Number(id));if(!t)throw new Error('Task not found.');const complete=t.status==='Completed';modal(t.title,`<div class="between" style="margin-bottom:15px"><span class="tiny muted">${esc(t.reference)}</span>${badge(t.status)}</div><div class="detail-box">${esc(t.description)}</div>${details({flow:t.flow,due_date:fmt(t.due_date,'full')})}${t.id===2&&!complete?'<div class="notice"><button class="link-button" data-action="task-goal">Add your goals in Performance</button>, then return to complete the task.</div>':''}${complete?`<h3 class="small">Your Response</h3><div class="detail-box" style="margin-top:10px">${esc(t.resolution)}</div><div class="form-actions"><button class="button" data-action="close-modal">Close</button><button class="button primary" data-action="reopen-task" data-id="${t.id}">Reopen Task</button></div>`:`<form data-form="task" data-id="${t.id}"><div class="field"><label for="task-response">Your Response</label><textarea name="resolution" id="task-response" minlength="3" maxlength="4000" required placeholder="Add your response, observations, or completion notes..."></textarea><small>Submitting completes this task in the local database.</small></div>${actions('Submit & Complete')}</form>`}`);}
async function openLeave(type='Earned Leave'){S.balances=await api('/leave-balances');const today=S.dashboard.server_time.slice(0,10);modal('Apply Leave',`<form data-form="leave"><div class="form-grid">${select('Leave Type','type',S.balances.map(b=>({value:b.type,label:b.type+(b.balance===null?'':` (${b.balance-b.pending_days} available)`)})),type)}<div></div>${field('From Date','start_date','date',today,'required')}${field('To Date','end_date','date',today,'required')}${area('Reason for Leave','reason','Briefly explain the reason for your request...')}</div><div class="notice blue" style="margin:17px 0 0"><strong id="leave-days">1 calendar day</strong><br>Leave calculation uses inclusive calendar days. Pending requests reserve available leave; approval deducts it. This is not an official company policy.</div>${actions('Submit Leave Request')}</form>`);}
function themeDialog(){
 closeOverlays();
 const themes=[['amex','American Express','Clean blue workspace'],['midnight','Midnight','Dark, high-contrast workspace'],['forest','Forest','Deep green professional theme'],['sand','Sand','Warm neutral workspace']];
 modal('Choose Workspace Theme',`<div class="theme-grid">${themes.map(([id,name,desc])=>`<button class="theme-choice ${S.theme===id?'active':''}" data-action="set-theme" data-theme="${id}"><span class="theme-preview ${id}"></span><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><p class="tiny muted" style="margin-top:16px">Theme is saved on this browser and does not change your account data.</p>`);
}
function preferences(){closeOverlays();const p={attendance_reminders:true,request_updates:true,weekly_summary:false,compact_view:false,...S.user.preferences};modal('Update Preferences',`<form data-form="preferences">${[['attendance_reminders','Attendance reminders','Save your preference for attendance reminders.'],['request_updates','Request updates','Save your preference for request updates.'],['weekly_summary','Weekly summary','Save your preference for a weekly summary.'],['compact_view','Compact view','Use compact table rows and page spacing.']].map(([k,t,b])=>`<label class="check-row"><div><strong>${t}</strong><p>${b}</p></div><input name="${k}" type="checkbox" ${p[k]?'checked':''}></label>`).join('')}<p class="tiny muted" style="margin-top:16px">Preferences save locally. No email or scheduled reminder delivery is configured.</p>${actions('Save Preferences')}</form>`);}
function ticket(category='IT Support'){modal('Raise a Support Ticket',`<form data-form="ticket"><div class="form-grid">${select('Category','category',['IT Support','Colleague Services','Helpdesk'],category)}${select('Priority','priority',['Low','Medium','High','Urgent'],'Medium')}<div class="field full"><label for="f-title">Subject</label><input id="f-title" name="title" required minlength="3" maxlength="150" placeholder="A short description of the issue"></div>${area('Describe the Issue','description','What happened, when did it start, and what have you tried? Do not include passwords.')}</div><p class="tiny muted" style="margin-top:13px">Saved locally for a response from the administrator.</p>${actions('Create Ticket')}</form>`);}
function goal(){const d=new Date();d.setDate(d.getDate()+30);modal('Add a Goal',`<form data-form="goal"><div class="form-grid"><div class="field full"><label for="f-title">Goal / Key Result Area</label><input id="f-title" name="title" required minlength="3" maxlength="150" placeholder="What would you like to achieve?"></div>${field('Target Date','target_date','date',d.toISOString().slice(0,10),'required')}${field('Starting Progress (%)','progress','number','0','required min="0" max="100" step="1"')}${area('Success Measures','description','Describe a clear, measurable result...','',false)}</div>${actions('Create Goal')}</form>`);}
function requestForm(kind='flow',title=''){let fields='',note='This request is saved locally for review by the administrator.';const today=S.dashboard.server_time.slice(0,10);
 if(kind==='flow')fields=select('Flow Type','flow_type',['Behavioral Management','Address Change','Work From Home Request','General HR Request'])+field('Request Title','title','text',title,'required minlength="3" maxlength="150"')+area('Request Details','reason','Describe what you need.');
 if(kind==='letter'){fields=select('Document Type','document_type',['Employment confirmation','Salary certificate','No-objection letter','Experience letter'],title.toLowerCase()==='salary certificate'?'Salary certificate':'Employment confirmation')+field('Addressed To','addressed_to','text','','maxlength="150"')+area('Purpose','purpose','Describe why you need the document.');note='This sends a request to HR. It does not generate a letter. Administrators publish offer letters and payslips through the Document Centre.';}
 if(kind==='expense')fields=field('Expense Title','title','text',title,'required minlength="3" maxlength="150"')+field('Amount (INR)','amount','number','','required min="0.01" max="1000000" step="0.01"')+field('Expense Date','date','date',today,'required')+select('Category','category',['Office supplies','Travel','Meals','Equipment','Other'])+area('Expense Details','description','Explain the business purpose. Receipt upload and payments are not connected.');
 if(kind==='travel'){fields=field('Destination','destination','text','','required maxlength="100"')+select('Travel Type','travel_type',['Business travel','Training','Event / conference','Other'])+field('Start Date','start_date','date',today,'required')+field('End Date','end_date','date',today,'required')+area('Purpose of Travel','purpose','Describe the purpose and arrangements needed.');note='Local travel request only. No tickets, hotels, payments or external booking integrations are connected.';}
 if(kind==='referral')fields=field('Candidate Name','candidate_name','text','','required maxlength="100"')+field('Candidate Email','candidate_email','email','','required maxlength="254"')+field('Role / Job Title','job_title','text',title,'required maxlength="150"')+field('Relevant Experience','experience','text','','maxlength="150"')+area('Why This Candidate?','reason','Describe relevant skills and experience with the candidate\'s permission.');
 if(kind==='regularization')fields=field('Shift Start Date','date','date',S.dashboard.shift_date,`required max="${today}"`)+field('Request Title','title','text','Attendance regularization','required maxlength="150"')+field('Correct Check In','clock_in','time',S.dashboard.shift.start_time,'required')+field('Check Out (next morning)','clock_out','time',S.dashboard.shift.end_time,'required')+area('Reason for Correction','reason','Explain the correction. When checkout is earlier than check-in, the next morning is used automatically.');
 if(kind==='tax'){fields=field('Request Title','title','text','Tax declaration review','required minlength="3" maxlength="150"')+field('Financial Year','financial_year','text','2026-27','required maxlength="15"')+area('Request Details','reason','Describe the assistance needed. Do not enter tax IDs or other sensitive information.');note='Local request only. No tax calculation, official declaration submission or payroll integration is performed.';}
 if(kind==='service')fields=field('Request Title','title','text',title,'required minlength="3" maxlength="150"')+select('Priority','priority',['Low','Medium','High'],'Medium')+area('How Can We Help?','reason','Describe the service you need.');
 modal(requestTitles[kind]||'New Request',`<form data-form="request" data-kind="${kind}"><div class="form-grid">${fields}</div><div class="notice ${kind==='letter'?'warning':'blue'}" style="margin:18px 0 0">${note}</div>${actions('Submit Request')}</form>`);
}
async function requestDetail(id){const data=await api('/requests'),r=data.find(x=>x.id===Number(id));if(!r)throw new Error('Request not found.');modal(r.title,`<div class="between"><span class="tiny muted">REQ-${String(r.id).padStart(4,'0')} \u00b7 ${fmt(r.created_at,'full')}</span>${badge(r.status)}</div>${details(r.details)}${r.admin_note?`<h3 class="small">Administrator Response</h3><div class="detail-box" style="margin-top:10px">${esc(r.admin_note)}</div>`:''}<div class="form-actions"><button class="button" data-action="close-modal">Close</button>${r.kind==='letter'?'<button class="button primary" data-action="open-my-documents">My documents</button>':''}</div>`);}
async function ticketDetail(id){const data=await api('/tickets'),r=data.find(x=>x.id===Number(id));if(!r)throw new Error('Ticket not found.');modal(r.title,`<div class="between" style="margin-bottom:18px"><span class="tiny muted">TKT-${String(r.id).padStart(4,'0')} \u00b7 ${esc(r.category)}</span>${badge(r.status)}</div><div class="detail-box">${esc(r.description)}</div>${details({priority:r.priority,created:fmt(r.created_at,'full')})}<h3 class="small">Administrator Response</h3><div class="detail-box" style="margin-top:10px">${esc(r.admin_note||'No response yet. Your ticket is in the local support queue.')}</div><div class="form-actions"><button class="button primary" data-action="close-modal">Done</button></div>`);}
async function review(kind, id) {
 try {
  if (!S.overview || !Array.isArray(S.overview[kind])) S.overview = await api('/admin/overview');
  const list = S.overview && Array.isArray(S.overview[kind]) ? S.overview[kind] : [];
  const r = list.find(x => Number(x.id) === Number(id));
  if (!r) throw new Error('Request not found. Please refresh the page.');
  const d = kind==='leaves'
   ? {type:r.type,from:r.start_date,to:r.end_date,days:r.days,reason:r.reason}
   : kind==='tickets'
    ? {category:r.category,priority:r.priority,description:r.description}
    : (r.details || {});
  const closed = kind!=='tickets' && r.status!=='Pending';
  const title = kind==='leaves' ? 'Leave Request' : kind==='tickets' ? 'Support Ticket' : 'Attendance Regularization';
  modal('Review '+title, `<div class="between"><div><strong class="small">${esc((r.first_name||'')+' '+(r.last_name||''))}</strong><p class="tiny muted">${esc(r.employee_id||'')}</p></div>${badge(r.status||'Pending')}</div>${details(d)}${closed?`<div class="detail-box">${esc(r.review_note||r.admin_note||'This request has already been reviewed.')}</div><div class="form-actions"><button class="button" data-action="close-modal">Close</button></div>`:`<form data-form="review" data-kind="${esc(kind)}" data-id="${Number(r.id)}"><div class="form-grid">${select('Decision / Status','status',kind==='tickets'?['Open','In progress','Resolved']:['Approved','Rejected'],kind==='tickets'?r.status:'Approved')}${area('Review Note','note','Add an explanation for the employee...',r.admin_note||'',false)}</div>${actions('Save Review')}</form>`}`);
 } catch (err) { toast(err.message || 'Unable to open the request.', true); }
}
function guide(){workspaceGuideV3();}
function shiftSettings(){closeOverlays();const shift=S.dashboard.shift;modal('Edit Overnight Shift',`<form data-form="shift-settings"><div class="notice blue">Standard shift: <strong>8:30 PM to 4:30 AM IST</strong>. This changes your saved workspace schedule. Your check-in and check-out timestamps are always recorded in IST.</div><div class="form-grid">${field('Shift starts','start_time','time',shift.start_time,'required')}${field('Ends next morning','end_time','time',shift.end_time,'required')}</div><p class="tiny muted" style="margin-top:16px">Set an overnight shift of 1 to 16 hours. Finish any active shift before saving changes.</p>${actions('Save Overnight Shift')}</form>`);}
async function punch(){
 const fresh=await api('/attendance/status');Object.assign(S.dashboard,fresh);S.clockSync=Date.now();
 if(fresh.state==='checked_out'){nav('time');toast('This shift is complete. Use an attendance correction for any changes.');return;}
 const out=fresh.state==='checked_in',early=!out&&Date.parse(fresh.server_time)<Date.parse(fresh.scheduled_start);
 modal(out?'Check Out of Your Shift':'Check In to Your Shift',`<div class="confirm-shift"><span class="shift-icon">${icon(out?'logout':'moon')}</span><strong>${shiftLabel()}</strong><span>${fmt(fresh.scheduled_start)} to ${fmt(fresh.scheduled_end)} &middot; IST</span></div><div class="notice blue">${out?'Your current shift will be completed and the elapsed work time will be saved, even after midnight.':early?'You are checking in before the scheduled start. Early check-in is enabled; the current server time will be saved.':'The current server time will be recorded and your live work timer will start.'}</div><p>${out?'Checked in: '+clock12(fresh.today.clock_in)+' &middot; '+fmt(fresh.today.clock_in,'full'):'One attendance record per shift. No company or biometric system is connected.'}</p><div class="form-actions"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-punch" data-mode="${out?'check-out':'check-in'}" data-id="${fresh.today?.id||''}">${icon(out?'logout':'login')} Confirm ${out?'Check Out':'Check In'}</button></div>`);
}
async function signOut(){try{await api('/auth/logout',{method:'POST'});}catch(e){if(e.status!==401)throw e;}closeModal();history.replaceState(null,'','#');S.epoch++;loginPage();}
let searchTimer;
document.addEventListener('input',e=>{const el=e.target;if(el.id==='app-search')appGrid(el.value);if(el.id==='task-search'){S.taskQ=el.value;S.taskPage=1;taskTable();}if(el.id==='member-search'){const q=el.value.toLowerCase();$('#member-grid').innerHTML=memberCards(S.members.filter(u=>(u.first_name+' '+u.last_name+' '+u.department+' '+u.employee_id).toLowerCase().includes(q)));}if(el.id==='job-search'){const q=el.value.toLowerCase();$('#job-grid').innerHTML=jobCards(S.jobs.filter(j=>(j.title+' '+j.department+' '+j.location).toLowerCase().includes(q)));}if(el.id==='people-search'){clearTimeout(searchTimer);$('#people-results')?.remove();const q=el.value;if(!q.trim())return;searchTimer=setTimeout(async()=>{try{const data=await api('/members?q='+encodeURIComponent(q));if($('#people-search')?.value!==q)return;$('.people-search').insertAdjacentHTML('beforeend',`<div id="people-results" class="search-results">${data.length?data.map(u=>`<button class="search-person" data-action="member" data-id="${u.id}">${avatar(u)}<div><strong class="small">${esc(u.first_name+' '+u.last_name)}</strong><p class="tiny muted">${esc(u.department)}</p></div></button>`).join(''):'<p class="no-match">No matching people.</p>'}</div>`);}catch(err){toast(err.message,true);}},220);}if(el.name==='start_date'||el.name==='end_date'){const f=el.closest('[data-form="leave"]');if(f){const days=Math.round((new Date(f.end_date.value)-new Date(f.start_date.value))/86400000)+1;$('#leave-days').textContent=days>0?`${days} calendar day${days===1?'':'s'}`:'Choose a valid date range';}}});
document.addEventListener('change',async e=>{try{if(e.target.id==='metrics-period'){S.period=e.target.value;await renderRoute();}if(e.target.id==='attendance-end'){S.end=e.target.value;await renderRoute();}if(e.target.id==='task-status'){S.taskStatus=e.target.value;S.taskPage=1;taskTable();}if(e.target.id==='task-size'){S.taskSize=Number(e.target.value);S.taskPage=1;taskTable();}}catch(err){toast(err.message,true);}});
document.addEventListener('click',async e=>{const route=e.target.closest('[data-nav]');if(route){e.preventDefault();nav(route.dataset.nav);return;}const el=e.target.closest('[data-action]');if(!el){if(!e.target.closest('.popover')&&!e.target.closest('.app-drawer')&&!e.target.closest('.people-search'))closeOverlays();return;}try{switch(el.dataset.action){
 case'apps':openApps();break;case'nav-time':nav('time');break;case'nav-attendance-edit':nav('attendance-admin');break;case'refresh':await renderRoute();break;case'close-overlays':closeOverlays();break;case'close-modal':closeModal();break;case'account':accountMenu();break;case'notifications':await notifications();break;case'guide':guide();break;case'reload':location.reload();break;case'retry':await renderRoute();break;
 case'read-notifications':await api('/notifications/read',{method:'POST'});S.dashboard.unread=0;$('#unread-count').textContent='0';await notifications();toast('All notifications marked as read.');break;
 case'task':await openTask(el.dataset.id);break;case'task-goal':closeModal();nav('performance');goal();break;case'reopen-task':await api('/tasks/'+el.dataset.id,{method:'PATCH',body:{status:'Pending',resolution:''}});closeModal();await refresh();toast('Task reopened.');break;
 case'task-tab':S.taskTab=el.dataset.tab;S.taskPage=1;await renderRoute();break;case'task-sort':S.ascending=!S.ascending;taskTable();break;case'task-prev':S.taskPage--;taskTable();break;case'task-next':S.taskPage++;taskTable();break;case'task-filters':S.filters=!S.filters;await renderRoute();break;case'clear-filters':S.taskQ='';S.taskStatus='';S.taskPage=1;await renderRoute();break;
 case'save-filters':if(localStore.getItem('portal-filters')){localStore.removeItem('portal-filters');toast('Saved filters cleared.');}else{localStore.setItem('portal-filters',JSON.stringify({q:S.taskQ,status:S.taskStatus,tab:S.taskTab}));toast('Current filters saved on this browser.');}await renderRoute();break;
 case'task-settings':modal('Task Table Settings',`<form data-form="task-settings">${select('Rows Per Page','size',['10','20','50'],String(S.taskSize))}${actions('Apply Settings')}</form>`);break;
 case'leave':await openLeave(el.dataset.type||'Earned Leave');break;
 case'cancel-leave':modal('Cancel Leave Request',`<p>Cancel this request? Approved paid leave will be restored to your balance.</p><div class="form-actions"><button class="button" data-action="close-modal">Keep Request</button><button class="button danger" data-action="confirm-cancel-leave" data-id="${el.dataset.id}">Cancel Leave</button></div>`);break;
 case'confirm-cancel-leave':await api('/leaves/'+el.dataset.id,{method:'DELETE'});closeModal();await refresh();toast('Leave request cancelled.');break;
 case'preferences':preferences();break;case'event':S.eventTab=el.dataset.tab;$$('.event-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===S.eventTab));$('#events-content').innerHTML=eventHTML();break;
 case'request':requestForm(el.dataset.kind,el.dataset.title||'');break;case'request-detail':await requestDetail(el.dataset.id);break;case'recommendation':if(el.dataset.kind==='profile')nav('profile');else requestForm(el.dataset.kind);break;
 case'ticket':ticket(el.dataset.category);break;case'ticket-detail':await ticketDetail(el.dataset.id);break;case'goal':goal();break;
 case'progress':{const g=S.goals.find(x=>x.id===Number(el.dataset.id));modal('Update Goal Progress',`<form data-form="progress" data-id="${g.id}"><p class="small" style="margin-bottom:17px">${esc(g.title)}</p>${field('Progress (%)','progress','number',g.progress,'required min="0" max="100" step="1"')}${actions('Save Progress')}</form>`);break;}
 case'delete-goal':modal('Delete Goal',`<p>Permanently delete this goal from the local database?</p><div class="form-actions"><button class="button" data-action="close-modal">Keep Goal</button><button class="button danger" data-action="confirm-delete-goal" data-id="${el.dataset.id}">Delete Goal</button></div>`);break;
 case'confirm-delete-goal':await api('/goals/'+el.dataset.id,{method:'DELETE'});closeModal();await renderRoute();toast('Goal deleted.');break;
 case'member':{const data=await api('/members'),u=data.find(x=>x.id===Number(el.dataset.id));if(!u)throw new Error('Member not found.');closeOverlays();modal(u.first_name+' '+u.last_name,`<div class="row">${avatar(u)}${badge('Employee')}</div>${details({employee_id:u.employee_id,designation:u.designation,department:u.department,location:u.location,email:u.email,reporting_manager:u.manager})}<div class="form-actions"><button class="button primary" data-action="close-modal">Done</button></div>`);break;}
 case'sign-out':await signOut();break;case'login-role':accessPage(el.dataset.role);break;
 case'password':passwordDialog();break;case'theme':themeDialog();break;case'set-theme':applyTheme(el.dataset.theme);themeDialog();toast('Workspace theme changed.');break;
 case'toggle-password':{const input=document.getElementById(el.dataset.target);const show=input.type==='password';input.type=show?'text':'password';el.textContent=show?'Hide':'Show';el.setAttribute('aria-label',(show?'Hide':'Show')+' password');break;}
 case'login-help':modal('Sign-in help','<p>Your administrator creates your account and provides a temporary password. Sign in with your email address or employee ID and choose the correct account type.</p><p style="margin-top:14px">For a forgotten password, ask your administrator to reset it. Password-reset emails are not configured.</p><div class="form-actions"><button class="button primary" data-action="close-modal">Close</button></div>');break;
 case'add-employee':employeeForm();break;case'edit-employee':employeeForm(el.dataset.id);break;
 case'upload-document':await uploadDocumentForm(el.dataset.employee||'');break;
 case'employee-balances':await employeeBalances(el.dataset.id);break;case'manager-leave-review':managerLeaveReview(el.dataset.id,el.dataset.status);break;
 case'open-my-documents':closeModal();nav('documents');break;
 case'reset-employee-password':modal('Reset employee password',`<p>Generate a new temporary password and sign this employee out of all sessions? They must change it on their next sign-in.</p><div class="form-actions"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="confirm-reset-password" data-id="${Number(el.dataset.id)}">Reset password</button></div>`);break;
 case'confirm-reset-password':{el.disabled=true;const r=await api('/admin/employees/'+el.dataset.id+'/reset-password',{method:'POST'});const user=S.employees.find(x=>x.id===Number(el.dataset.id));await refresh();credentialsDialog(user,r.temporary_password);break;}
 case'copy-password':{const value=$('#issued-password').value;try{await navigator.clipboard.writeText(value);toast('Temporary password copied. Share it privately.');}catch{$('#issued-password').select();toast('Password selected. Press Ctrl+C to copy.');}break;}
 case'archive-document':modal('Archive this document?',`<p>The employee will no longer be able to download this file. Administrators retain it in the archived register. You can then publish a replacement.</p><div class="form-actions"><button class="button" data-action="close-modal">Keep document</button><button class="button danger" data-action="confirm-archive" data-id="${Number(el.dataset.id)}">Archive document</button></div>`);break;
 case'confirm-archive':el.disabled=true;await api('/admin/documents/'+el.dataset.id+'/archive',{method:'POST'});closeModal();await refresh();toast('Document archived.');break;
 case'shift-settings':shiftSettings();break;case'punch':await punch();break;case'confirm-punch':el.disabled=true;{const out=el.dataset.mode==='check-out';const r=await api('/attendance/'+(out?'check-out':'check-in'),{method:'POST',body:out?{attendance_id:Number(el.dataset.id)}:{}});closeModal();await refresh();toast(r.message+(out?'. Attendance saved.':'. Your shift timer is running.'));}break;
 case'admin-tab':S.adminTab=el.dataset.tab;$$('.tab[data-action="admin-tab"]').forEach(t=>t.classList.toggle('active',t.dataset.tab===S.adminTab));adminTable();break;case'edit-admin-attendance':editAdminAttendance(el.dataset.date);break;case'review':await review(el.dataset.kind,el.dataset.id);break;
 }}catch(err){el.disabled=false;toast(err.message,true);}});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f)),submit=$('button[type="submit"]',f),error=$('.error-text',f);if(error)error.textContent='';if(submit)submit.disabled=true;try{let message='Saved.';switch(f.dataset.form){
 case'login':{const info=await api('/auth/login',{method:'POST',body:data});S.user=info.user;S.csrf=info.csrf;loadAccountTheme();S.route='dashboard';history.replaceState(null,'','#dashboard');if(S.user.must_change_password){changePasswordPage();return;}await refresh();toast('Signed in.');return;}
 case'setup':{const info=await api('/auth/setup',{method:'POST',body:data});S.user=info.user;S.csrf=info.csrf;loadAccountTheme();S.route='employees';history.replaceState(null,'','#employees');await refresh();toast('Administrator created. Add your employee accounts.');return;}
 case'password':{const info=await api('/auth/password',{method:'POST',body:data});S.user=info.user;S.csrf=info.csrf;loadAccountTheme();closeModal();if(f.dataset.required)history.replaceState(null,'','#dashboard');await refresh();toast('Password changed.');return;}
 case'employee':{const edit=!!f.dataset.id;const payload={...data,...(edit?{is_active:data.is_active==='true'}:{})};const r=await api('/admin/employees'+(edit?'/'+f.dataset.id:''),{method:edit?'PATCH':'POST',body:payload});closeModal();await refresh();if(edit)toast('Account updated.');else credentialsDialog(r.user,r.temporary_password);return;}
 case'employee-balances':await api('/admin/employees/'+f.dataset.id+'/leave-balances',{method:'PATCH',body:{balances:data}});message='Leave balances saved.';break;
 case'upload-document':{const form=new FormData(f),file=form.get('file');if(!file||!file.size)throw new Error('Select a PDF file.');if(file.size>10*1024*1024)throw new Error('The file exceeds the 10 MB limit.');if(!file.name.toLowerCase().endsWith('.pdf'))throw new Error('Only PDF documents are accepted.');await api('/admin/documents',{method:'POST',body:form});message='Document published to the selected employee.';break;}

 case'shift-settings':await api('/shift',{method:'PATCH',body:data});message='Night-shift schedule saved.';break;
 case'profile':await api('/profile',{method:'PATCH',body:{first_name:data.first_name,last_name:data.last_name,phone:data.phone,location:data.location}});message='Profile changes saved.';break;
 case'preferences':{const p={};['attendance_reminders','request_updates','weekly_summary','compact_view'].forEach(k=>p[k]=!!f.elements[k].checked);await api('/preferences',{method:'PATCH',body:p});message='Preferences saved.';break;}
 case'task':await api('/tasks/'+f.dataset.id,{method:'PATCH',body:{status:'Completed',resolution:data.resolution}});message='Task completed. Your response was saved.';break;
 case'leave':await api('/leaves',{method:'POST',body:data});message='Leave request submitted for administrator review.';break;
 case'ticket':{const r=await api('/tickets',{method:'POST',body:data});message=`Ticket TKT-${String(r.id).padStart(4,'0')} created.`;break;}
 case'goal':await api('/goals',{method:'POST',body:{...data,progress:Number(data.progress)}});message='Goal created.';break;
 case'progress':await api('/goals/'+f.dataset.id,{method:'PATCH',body:{progress:Number(data.progress)}});message='Goal progress updated.';break;
 case'admin-attendance':{const uid=Number(f.dataset.userId);await api('/admin/attendance/'+uid,{method:'PATCH',body:data});message='Attendance updated.';break;}
 case'request':{const kind=f.dataset.kind;if(kind==='travel'&&data.end_date<data.start_date)throw new Error('End date must be on or after start date.');const title=data.title||data.document_type||(kind==='travel'?'Travel to '+data.destination:kind==='referral'?'Referral: '+data.candidate_name:requestTitles[kind]);const r=await api('/requests',{method:'POST',body:{kind,title,details:data}});message=`Request REQ-${String(r.id).padStart(4,'0')} submitted.`;break;}
 case'manager-leave-review':await api('/manager/leaves/'+f.dataset.id,{method:'PATCH',body:data});message='Leave review saved.';break;
 case'review':await api('/admin/'+f.dataset.kind+'/'+f.dataset.id,{method:'PATCH',body:data});message='Review saved. The employee can see the updated status.';break;
 case'post':await api('/posts',{method:'POST',body:data});message='Your update was shared with the local team.';break;
 case'task-settings':S.taskSize=Number(data.size);S.taskPage=1;message='Table settings applied.';break;
 default:throw new Error('Unknown form. Refresh and try again.');}
 closeModal();await refresh();toast(message);
 }catch(err){if(error)error.textContent=err.message;else toast(err.message,true);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='employee-search'){$('#employees-table').innerHTML=employeeTable(S.employees.filter(u=>(u.first_name+' '+u.last_name+' '+u.email+' '+u.employee_id).toLowerCase().includes(e.target.value.toLowerCase())));}if(e.target.id==='admin-doc-search'){S.documentSearch=e.target.value;$('#admin-documents-table').innerHTML=adminDocumentsTable();}});
document.addEventListener('change',async e=>{const el=e.target;
if(el.id==='profile-photo-file'){try{const file=el.files[0];if(!file)return;if(file.size>5*1024*1024)throw new Error('The profile photo exceeds 5 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Only JPG, PNG, or WEBP photos are accepted.');const form=new FormData();form.append('file',file);const u=await api('/profile/photo',{method:'POST',body:form});S.user=u;await refresh();toast('Profile photo updated.');}catch(err){toast(err.message,true);}return;}if(el.id==='admin-attendance-employee'){S.adminAttendanceEmployee=Number(el.value);await renderRoute();return;}if(el.id==='admin-doc-kind'){S.documentFilter=el.value;$('#admin-documents-table').innerHTML=adminDocumentsTable();}if(el.id==='show-archived'){S.includeArchived=el.checked;$('#admin-documents-table').innerHTML=adminDocumentsTable();}if(el.id==='my-doc-period'){$('#my-documents-table').innerHTML=personalDocumentTable(S.myDocuments.filter(d=>!el.value||d.pay_period===el.value),true);}if(el.name==='kind'&&el.closest('[data-form="upload-document"]')){const period=$('#f-pay_period');period.required=el.value==='payslip';period.disabled=el.value!=='payslip';period.closest('.field').hidden=el.value!=='payslip';}if(el.id==='f-file'){$('#selected-file-name').textContent=el.files[0]?el.files[0].name+' / '+fileSize(el.files[0].size):'No file selected';}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlays();});
$('#modal').addEventListener('close',()=>{if(!$('#modal').open)$('#modal').innerHTML='';});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if(S.user&&!S.user.must_change_password){window.scrollTo(0,0);renderRoute();}});
try{const f=JSON.parse(localStore.getItem('portal-filters')||'null');if(f){S.taskQ=f.q||'';S.taskStatus=f.status||'';S.taskTab=f.tab||'my';}}catch(e){localStore.removeItem('portal-filters');}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&S.user&&!S.user.must_change_password&&!$('#modal').open)refresh().catch(()=>{});});
start();
